select t.BOOKSET_ID_TMPL from (
      select BOOKSET_ID_TMPL,row_number() over() as rownum
      from BOK_BOOKSET a
      where a.acct_subject_id = #{prodId,jdbcType=VARCHAR}
) t where t.rownum = 1

select trim(p.mySubjectId) as mySubjectId, trim(p.othersideSubjectId) as othersideSubjectId, trim(p.blockType) as blockType from (select a.MY_SUBJECT_ID mySubjectId, a.OTHERSIDE_SUBJECT_ID othersideSubjectId, a.BLOCK_TYPE blockType from BOK_SCHEME_SUBJECT_CONFIG a where a.SCHEME_ID = #{schemeId,jdbcType=VARCHAR} and a.my_subject_id is not null and a.otherside_subject_id is not null
union all select a.my_subject_id || b.my_asset_id mySubjectId, a.otherside_subject_id || b.otherside_asset_id othersideSubjectId, a.BLOCK_TYPE blockType from BOK_SCHEME_SUBJECT_CONFIG a INNER JOIN BOK_SCHEME_ASSET_CONFIG b on b.scheme_id = a.scheme_id where 1=1 and a.IS_GEN_SUBS = 'Y' and a.scheme_id = #{schemeId,jdbcType=VARCHAR} and a.my_subject_id is not null and a.otherside_subject_id is not null and ( a.my_subject_id || b.my_asset_id in
#{idString}
or a.otherside_subject_id || b.otherside_asset_id in
#{idString}
) ) p order by p.mySubjectId

