delete from BOK_PRODUCT_COL_RESULT col
where exists (
    select 1 from BOK_PRODUCT_ROW_RESULT rowR 
    where rowR.COMPARE_ID = col.COMPARE_ID and rowR.PROD_ID = #{prodId,jdbcType=VARCHAR} and rowR.SCHEME_ID = #{schemeId,jdbcType=VARCHAR} and rowR.COMPARE_DATE = #{compareDate,jdbcType=DATE}
)

