select rowR.COMPARE_ID, rowR.PROD_ID, rowR.SCHEME_ID, rowR.COMPARE_DATE, rowR.COMPARE_TYPE, rowR.COMPARE_ROWNO, rowR.MY_SUBJECT_ID, rowR.MY_SUBJECT_NAME, rowR.OTHERSIDE_SUBJECT_ID, rowR.OTHERSIDE_SUBJECT_NAME, rowR.REMARK, colR.COMPARE_COL, colR.MY_DATA, colR.OTHERSIDE_DATA, colR.NEEDCOMPARE, colR.DIFFERENCE from BOK_VALBAL_TABLE_STATUS pvm inner join BOK_PRODUCT_ROW_RESULT rowR on rowR.SCHEME_ID = #{schemeId} and rowR.PROD_ID = pvm.FINPROD_ID and rowR.COMPARE_DATE = pvm.VAL_DATE inner join BOK_PRODUCT_COL_RESULT colR on colR.COMPARE_ID = rowR.COMPARE_ID /**left join BOK_SUBJECT bsOTH on bsOTH.SUBJECT_NO = rowR.OTHERSIDE_SUBJECT_ID and **/ where pvm.FINPROD_ID = #{prodId} AND pvm.VAL_DATE = to_date(#{valueDate,jdbcType=DATE}, 'yyyy-MM-dd') AND pvm.VAL_BAL_FLAG = #{schemeType,jdbcType=VARCHAR}
and rowR.COMPARE_TYPE = #{compareType,jdbcType=VARCHAR}
and colR.NEEDCOMPARE = '01'
#{item,jdbcType=VARCHAR}
order by rowR.COMPARE_ROWNO

