select * from ( /**3级科目号**/ select bs.subject_no as subjectId, bs.subject_no as threeSubject, null as myAssetId, null as mappingAssetId, bs.base_subject_nature as nature from BOK_SUBJECT bs where bookset_id = #{booksetId,jdbcType=VARCHAR} and bs.base_subject_nature is not null and bs.subject_level = '3' and exists( select 'X' from BOK_SCHEME_NATURE_CONFIG ng where ng.scheme_id = #{schemeId,jdbcType=VARCHAR} and ng.my_nature_id = bs.base_subject_nature ) and bs.subject_no in
#{idString}
union all /**四级科目号**/ select bs.subject_no || ast.my_asset_id as subjectId, bs.subject_no as threeSubject, ast.my_asset_id as myAssetId, ast.otherside_asset_id as mappingAssetId, bs.base_subject_nature as nature from BOK_SUBJECT bs inner join BOK_SCHEME_ASSET_CONFIG ast on 1=1 where bs.bookset_id = #{booksetId,jdbcType=VARCHAR} and bs.base_subject_nature is not null and bs.subject_level = '3' and ast.scheme_id = #{schemeId,jdbcType=VARCHAR} and exists( select 'X' from BOK_SCHEME_NATURE_CONFIG ng where ng.my_nature_id = bs.base_subject_nature and ng.scheme_id = ast.scheme_id ) and not exists(/**排除该科目在科目映射表中，是否扩展四级科目号为【否】的资产数据。**/ select 'X' from BOK_SCHEME_SUBJECT_CONFIG bc where nvl(bc.is_gen_subs,'N') = 'N' and bc.scheme_id = ast.scheme_id and bc.my_subject_id = bs.subject_no ) and bs.subject_no || ast.my_asset_id in
#{idString}
)

select * from ( /**不可扩展的3级科目号**/ select ng.otherside_subject_id as subjectId, ng.otherside_subject_id as threeSubject, null as myAssetId, null as mappingAssetId, ng.my_nature_id as nature from BOK_SCHEME_NATURE_CONFIG ng where ng.scheme_id = #{schemeId,jdbcType=VARCHAR} and exists( select 'X' from BOK_SUBJECT bs where bs.bookset_id = #{booksetId,jdbcType=VARCHAR} and bs.base_subject_nature is not null and bs.subject_level = '3' and ng.my_nature_id = bs.base_subject_nature ) and ng.otherside_subject_id in
#{idString}
union all
/**可扩展3级科目对应的四级科目号**/ select ng.otherside_subject_id || ast.otherside_asset_id as subjectId, ng.otherside_subject_id as threeSubject, ast.otherside_asset_id as myAssetId, ast.my_asset_id as mappingAssetId, ng.my_nature_id as nature from BOK_SCHEME_NATURE_CONFIG ng inner join BOK_SCHEME_ASSET_CONFIG ast on ast.scheme_id = ng.scheme_id where ng.scheme_id = #{schemeId,jdbcType=VARCHAR} and exists( select 'X' from BOK_SUBJECT bs where bs.bookset_id = #{booksetId,jdbcType=VARCHAR} and bs.base_subject_nature is not null and bs.subject_level = '3' and ng.my_nature_id = bs.base_subject_nature ) and not exists(/**排除该科目在科目映射表中，是否扩展四级科目号为【否】的资产数据。**/ select 'X' from BOK_SCHEME_SUBJECT_CONFIG bc where nvl(bc.is_gen_subs,'N') = 'N' and bc.scheme_id = ng.scheme_id and bc.otherside_subject_id = ng.otherside_subject_id ) and ng.otherside_subject_id || ast.otherside_asset_id in
#{idString}
)m


